command_line:
set +e
cat > tiny.wdl <<'EOF'
version 1.0
workflow tiny {
  call hello
  output { String msg = hello.msg }
}
task hello {
  command <<<
    echo hello > out.txt
  >>>
  output { String msg = read_string("out.txt") }
  runtime { docker: "ubuntu:20.04" }
}
EOF
java -Dconfig.file=/dev/null -jar "/jetstream2/scratch/main/jobs/79144307/inputs/dataset_4e2822c8-16f6-429e-b8f1-098457f8011c.dat" run tiny.wdl > cromwell.stdout 2> cromwell.stderr
run_status=$$?
find cromwell-executions -maxdepth 5 -type f | sort > files.txt 2>/dev/null
{
  echo '--- status ---'
  echo "run_status $$run_status"
  echo '--- stdout ---'
  sed -n '1,180p' cromwell.stdout
  echo '--- stderr ---'
  sed -n '1,260p' cromwell.stderr
  echo '--- files ---'
  sed -n '1,160p' files.txt
} > probe.txt
exit 0
